CREATE TABLE IF NOT EXISTS notification_preferences (email TEXT PRIMARY KEY,email_enabled BOOLEAN NOT NULL DEFAULT TRUE,push_enabled BOOLEAN NOT NULL DEFAULT FALSE,news BOOLEAN NOT NULL DEFAULT TRUE,apps BOOLEAN NOT NULL DEFAULT TRUE,music BOOLEAN NOT NULL DEFAULT TRUE,videos BOOLEAN NOT NULL DEFAULT TRUE,projects BOOLEAN NOT NULL DEFAULT TRUE,events BOOLEAN NOT NULL DEFAULT TRUE,releases BOOLEAN NOT NULL DEFAULT TRUE,updated_at TIMESTAMPTZ NOT NULL DEFAULT now())